CREATE TABLE CPF_BATCH_EXECUTION_CONTROL_R89_BAK AS TABLE CPF_BATCH_EXECUTION_CONTROL;
CREATE TABLE CPF_BATCH_EXECUTION_EPOCH_R89_BAK AS TABLE CPF_BATCH_EXECUTION_EPOCH;
DO $$ BEGIN
  IF EXISTS (SELECT idempotency_key FROM CPF_BATCH_EXECUTION_CONTROL GROUP BY idempotency_key HAVING COUNT(*) > 1) THEN
    RAISE EXCEPTION 'R89 cannot restore global idempotency uniqueness; checkpoint retained';
  END IF;
END $$;
DROP TABLE CPF_BATCH_EXECUTION_EPOCH;
DROP INDEX IX_CPF_BAT_EXEC_RECONCILE;
DROP INDEX UK_CPF_BAT_EXEC_IDEM_SCOPE;
ALTER TABLE CPF_BATCH_EXECUTION_CONTROL
  DROP CONSTRAINT CK_CPF_BAT_REQUEST_HASH,
  DROP CONSTRAINT CK_CPF_BAT_PLAN_HASH,
  DROP CONSTRAINT CK_CPF_BAT_CONTROL_VERSION,
  DROP CONSTRAINT CK_CPF_BAT_RECONCILE_ATTEMPT,
  DROP COLUMN idempotency_scope,
  DROP COLUMN request_hash,
  DROP COLUMN plan_checksum,
  DROP COLUMN control_version,
  DROP COLUMN reconcile_attempts,
  DROP COLUMN reconcile_after,
  DROP COLUMN last_error_code,
  DROP COLUMN last_error_detail,
  ADD CONSTRAINT UK_CPF_BAT_EXEC_IDEM_LEGACY UNIQUE(idempotency_key);
